const sectionName=(p:Profile,id:string|null)=>p.sections.find(s=>s.id===id)?.name??'Unsorted'
function descendants(p:Profile,id:string){const ids=new Set([id]);let changed=true;while(changed){changed=false;p.sections.forEach(s=>{if(s.parentId&&ids.has(s.parentId)&&!ids.has(s.id)){ids.add(s.id);changed=true}})}return ids}
