function optionLabel(i:number){return i<26?String.fromCharCode(65+i):'Option '+(i+1)}
function shuffled<T>(items:T[]):T[]{const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
