 function submitExam(){if(examSubmitted)return;const answers={...examAnswers};if(active)answers[active.id]=selected;const scored=session.map(id=>{const q=profile.questions.find(q=>q.id===id);return !!q&&isCorrect(answers[id]??[],q.correctOptionIds)});setExamAnswers(answers);setLastExamResults(scored);setExamSubmitted(true);setRemainingSeconds(0);const limit=Math.max(1,Number(examMinutes)||10)*60;const record:ExamSession={id:uid(),at:new Date().toISOString(),source:setupSource,timeLimitSeconds:limit,durationSeconds:Math.max(0,limit-remainingSeconds),responses:session.map((questionId,i)=>({questionId,selectedOptionIds:answers[questionId]??[],correct:scored[i]})),score:scored.filter(Boolean).length};updateProfile(p=>({...p,exams:[...(p.exams??[]),record]}));setView('results')}
