 function saveQuestion(){const options=optionText.split('\n').map(s=>s.trim()).filter(Boolean);const indices=[...new Set(answer.split(',').map(s=>Number(s.trim())-1).filter(n=>Number.isInteger(n)&&n>=0&&n<options.length))];if(!questionText.trim()){setEditorError('Enter a question before saving.');return}if(options.length<2){setEditorError('Add at least two non-empty answer options.');return}if(!indices.length){setEditorError('Select at least one valid correct option number.');return}if((editorMode==='single'&&indices.length!==1)||(editorMode==='exactly-n'&&indices.length<2)){setEditorError(editorMode==='single'?'Choose exactly one correct option.':'Choose at least two correct options for Pick exactly N.');return}setEditorError('');const old=profile.questions.find(q=>q.id===editingId);const now=new Date().toISOString();const optionRecords=options.map((text,i)=>({id:old?.options.find(o=>o.text===text)?.id??uid(),text}));const q:Question={id:old?.id??uid(),prompt:questionText.trim(),options:optionRecords,correctOptionIds:indices.map(i=>optionRecords[i].id),answerMode:editorMode,sectionId:editorSectionId||null,explanation,tags:[...new Set(tagText.split(',').map(t=>t.trim()).filter(t=>t&&t!=='AI-Generated'&&t!=='AI-Extracted'))],createdAt:old?.createdAt??now,updatedAt:now,...(old?.sourceImportId?{sourceImportId:old.sourceImportId}:{}),...(old?.sourceFileName?{sourceFileName:old.sourceFileName}:{}),...(old?.provenance?{provenance:old.provenance}:{}),...(questionSource!=='unknown'?{source:questionSource}:{})};updateProfile(p=>({...p,questions:old?p.questions.map(x=>x.id===old.id?q:x):[...p.questions,q]}));setQuestionText('');setExplanation('');setTagText('');setQuestionSource('unknown');setShowQuestionForm(false);setEditingId(null)}
