 function exportJson(full=true,allProfiles=true){const data=full?{format:'freequiz/backup-v1',backupVersion:1,exportedAt:new Date().toISOString(),activeProfileId:allProfiles?store.activeProfileId:profile.id,profiles:allProfiles?store.profiles:[profile]}:exportQuestions(profile);const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=full?(allProfiles?'freequiz-all-profiles-backup.json':'freequiz-profile-backup.json'):'freequiz-questions.json';a.click();URL.revokeObjectURL(url)}
 function exportImport(batch:ImportBatch){const used=new Set(batch.questions.map(q=>q.sectionId).filter((id):id is string=>!!id));let changed=true;while(changed){changed=false;batch.sections.forEach(s=>{if(used.has(s.id)&&s.parentId&&!used.has(s.parentId)){used.add(s.parentId);changed=true}})}const data={format:'freequiz/questions-v1',sections:batch.sections.filter(s=>used.has(s.id)),questions:batch.questions};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(batch.name||'freequiz-import').replace(/[^a-z0-9-_]+/gi,'-')+'.json';a.click();URL.revokeObjectURL(url)}
 async function readFile(file?:File){if(!file)return;try{setJson(await file.text());setImportName(file.name.replace(/\.json$/i,''));setSourceFileName(file.name);setImportSource('json');setError('');setPreview(null);setBackupPreview(null)}catch{setError('Could not read this file.')}}
 function validate(){try{const raw=JSON.parse(json);if(raw?.format==='freequiz/backup-v1'){setBackupPreview(parseBackup(raw));setPreview(null)}else{setPreview(parseImport(raw));setBackupPreview(null)}setError('')}catch(e){setPreview(null);setBackupPreview(null);setError(e instanceof Error?e.message:'Invalid JSON.')}}
 function restoreBackup(){if(!backupPreview)return;const incoming=backupPreview.profiles;const usedIds=new Set(store.profiles.map(p=>p.id));const usedNames=new Set(store.profiles.map(p=>p.name.trim().toLocaleLowerCase()));const idMap=new Map<string,string>();const restored:Profile[]=incoming.map(original=>{let id=original.id;if(usedIds.has(id))id=uid();usedIds.add(id);idMap.set(original.id,id);let name=original.name;const base=name;let suffix=1;while(usedNames.has(name.trim().toLocaleLowerCase())){name=base+' (restored'+(suffix>1?' '+suffix:'')+')';suffix++}usedNames.add(name.trim().toLocaleLowerCase());return {...original,id,name}});const activeProfileId=idMap.get(backupPreview.activeProfileId)??restored[0].id;const summary='Restore '+restored.length+' profile '+(restored.length===1?'copy':'copies')+'? Existing profiles will remain unchanged. Any profile ID or name collisions will be adjusted; question, attempt, import, group, and exam IDs and all learning history will be preserved.';if(!window.confirm(summary))return;setStore(s=>({...s,profiles:[...s.profiles,...restored],activeProfileId}));setBackupPreview(null);setPreview(null);setJson('');setError('');setView('overview')}
 function applyImport(replace:boolean){if(!preview)return;updateProfile(p=>{const batchId=uid();const now=new Date().toISOString();const inferred=preview.questions.some(q=>q.provenance==='AI-Extracted')?'ai-extract':preview.questions.some(q=>q.provenance==='AI-Generated')?'ai-generate':'unknown';const addedQuestionIds=replace?preview.questions.map(q=>q.id):preview.questions.filter(q=>!p.questions.some(old=>old.id===q.id)).map(q=>q.id);const addedSet=new Set(addedQuestionIds);const imported=preview.questions.map(q=>addedSet.has(q.id)?({...q,sourceImportId:batchId,...(sourceFileName?{sourceFileName}:{}),createdAt:q.createdAt??now,updatedAt:now}):q);const sections=replace?preview.sections:[...p.sections,...preview.sections.filter(s=>!p.sections.some(old=>old.id===s.id))];const questions=replace?imported:[...p.questions,...imported.filter(q=>!p.questions.some(old=>old.id===q.id))];const ids=new Set(questions.map(q=>q.id));const batch:ImportBatch={id:batchId,name:importName.trim()||'Import '+new Date().toLocaleDateString(),at:now,source:importSource==='unknown'?inferred:importSource,addedQuestionIds,sections:preview.sections.map(s=>({...s})),questions:preview.questions.map(q=>({...q,options:q.options.map(o=>({...o})),correctOptionIds:[...q.correctOptionIds],tags:[...(q.tags??[])]})),...(sourceFileName?{sourceFileName,sourceIdentity:sourceFileName}:{})};return{...p,sections,questions,imports:[...(p.imports??[]),batch],attempts:replace?[]:p.attempts,favourites:(p.favourites??[]).filter(id=>ids.has(id)),groups:(p.groups??[]).map(g=>({...g,questionIds:g.questionIds.filter(id=>ids.has(id))}))}});setPreview(null);setBackupPreview(null);setJson('');setImportName('Manual import');setImportSource('unknown');setView('library')}
