 function sectionPickerTree(parent:string|null,depth=0):ReactNode{return profile.sections.filter(s=>s.parentId===parent).map(s=>{const term=sectionSearch.toLowerCase().trim();const childMatches=profile.sections.some(c=>c.id!==s.id&&descendants(profile,s.id).has(c.id)&&c.name.toLowerCase().includes(term));const selfMatches=s.name.toLowerCase().includes(term);return selfMatches||childMatches?<div key={s.id}><label style={{paddingLeft:4+depth*16}}><input type="checkbox" checked={selectedSectionIds.includes(s.id)} onChange={e=>setSelectedSectionIds(ids=>e.target.checked?[...new Set([...ids,...descendants(profile,s.id)])]:ids.filter(id=>!descendants(profile,s.id).has(id)))}/><span>{s.name}</span><small>{profile.questions.filter(q=>descendants(profile,s.id).has(q.sectionId??'')).length}</small></label>{sectionPickerTree(s.id,depth+1)}</div>:null})}
