 {view==='practice'&&<div className="page"><div className="practice-top"><div><p className="subtitle">{session.length?'Question '+Math.min(index+1,session.length)+' of '+session.length:'Choose a practice mode to get started.'}</p></div><button className="button button-quiet" onClick={()=>{const message=examMode?'Exit this exam without submitting? Your answers will not be saved as exam results.':'Exit this practice session? Answers already checked are saved, but this session will not resume.';if(window.confirm(message))setView('overview')}}><X size={15}/> Exit session</button></div>
 {!session.length?<div className="panel no-questions"><span className="empty-icon"><Brain size={26}/></span><h2>No questions in this session</h2><p>Try another mode or import more questions to your library.</p><button className="button button-primary" onClick={()=>start('all')}>Practise all</button></div>:active&&<div className="quiz-layout"><div className="quiz-main"><div className="quiz-progress"><span style={{width:((index+(revealed?1:0))/session.length*100)+'%'}}/></div><div className="question-meta"><span className="pill">{sectionName(profile,active.sectionId)}</span><span className="muted">Question {index+1}</span></div><h2 className="question-title"><MathText text={active.prompt}/></h2><p className="muted answer-hint">{examMode?`Exam mode · ${Math.floor(remainingSeconds/60)}:${String(remainingSeconds%60).padStart(2,'0')} remaining`:answerMode(active)==='single'?'Choose one answer.':answerMode(active)==='exactly-n'?`Select exactly ${active.correctOptionIds.length} answers.`:'Select all that apply.'}</p><div className="answer-list">{orderedOptions.map((o,i)=>{const chosen=selected.includes(o.id),correct=active.correctOptionIds.includes(o.id);return <button key={o.id} className={'answer-option '+(chosen?'chosen ':'')+(!examMode&&revealed&&correct?'answer-correct ':'')+(!examMode&&revealed&&chosen&&!correct?'answer-wrong':'')} onClick={()=>{if(!revealed&&!examSubmitted)setSelected(old=>old.includes(o.id)?old.filter(x=>x!==o.id):answerMode(active)==='single'?[o.id]:[...old,o.id])}}><span className="option-letter">{optionLabel(i)}</span><span><MathText text={o.text}/></span>{!examMode&&revealed&&correct&&<Check size={17}/>}</button>})}</div>
 {!examMode&&revealed&&<div className={'feedback-box '+(isCorrect(selected,active.correctOptionIds)?'feedback-good':'feedback-bad')}><div className="feedback-title">{isCorrect(selected,active.correctOptionIds)?<Check size={17}/>:<CircleHelp size={17}/>} {isCorrect(selected,active.correctOptionIds)?'Correct. Nice work.':'Not quite. Keep it in rotation.'}</div>{active.explanation&&<p><MathText text={active.explanation}/></p>}<small>Mastery: <strong>{labels[masteryFor(profile.attempts,active.id)]}</strong></small></div>}
 <div className="quiz-footer"><span className="muted">{index+1} / {session.length} · {Object.values(results).filter(Boolean).length} correct</span><button className="button button-quiet" onClick={deferCurrent} disabled={!active||(!examMode&&revealed)}>{examMode?"Mark deferred":"Defer"}</button>{!examMode&&<button className="button button-quiet" onClick={()=>toggleFavourite(active.id)} aria-pressed={(profile.favourites??[]).includes(active.id)}><Star size={14} fill={(profile.favourites??[]).includes(active.id)?"currentColor":"none"}/>{(profile.favourites??[]).includes(active.id)?"Favourited":"Favourite"}</button>}{examMode?<><button className="button button-quiet" onClick={()=>{const a={...examAnswers,[active.id]:selected};setExamAnswers(a);if(index>0){setIndex(i=>i-1);setSelected(a[session[index-1]]??[])}}} disabled={index===0}>Previous</button><button className="button button-primary" onClick={()=>{const a={...examAnswers,[active.id]:selected};setExamAnswers(a);if(index+1>=session.length)submitExam();else{setIndex(i=>i+1);setSelected(a[session[index+1]]??[])}}}>{index+1===session.length?'Submit exam':'Next question'} <ChevronRight size={15}/></button><button className="button button-quiet" onClick={submitExam}>Finish now</button></>:!revealed?<button className="button button-primary" disabled={!selected.length} onClick={check}>Check answer <ChevronRight size={15}/></button>:<button className="button button-primary" onClick={next}>{index+1===session.length?'View results':'Next question'} <ChevronRight size={15}/></button>}</div></div><aside className="quiz-aside"><div className="panel session-card"><p className="eyebrow">SESSION</p><h3>{examMode?'Exam progress':'Practice summary'}</h3><div className="session-stat"><span>Answered</span><strong>{examMode?Object.keys(examAnswers).length+(selected.length&&!examAnswers[active?.id??'']?1:0):Object.keys(results).length} / {session.length}</strong></div><div className="session-stat"><span>Correct</span><strong>{examMode?'Hidden until end':Object.values(results).filter(Boolean).length}</strong></div><div className="session-stat"><span>Accuracy</span><strong>{examMode?'—':Object.keys(results).length?Math.round(Object.values(results).filter(Boolean).length/Object.keys(results).length*100)+'%':'—'}</strong></div></div><div className="tip-card"><Sparkles size={17}/><strong>Take your time</strong><p>Try to recall the answer before looking at the options. Confidence grows with active recall.</p></div></aside></div>}</div>}
